+pcapio_writer*
+writecap_fopen(const char *filename, wtap_compression_type ctype, int *err)
+{
+    pcapio_writer* pfile;
+    *err = 0;
+
+    pfile = g_new0(struct pcapio_writer, 1);
+    if (pfile == NULL) {
+        *err = errno;
