+{
+    pcapio_writer* pfile;
+    *err = 0;
+
+    pfile = g_new0(struct pcapio_writer, 1);
+    if (pfile == NULL) {
+        *err = errno;
+        return NULL;
+    }
+    pfile->ctype = ctype;
+    errno = WTAP_ERR_CANT_OPEN;
+    WFILE_T fh = writecap_file_fdopen(pfile, fd);
+    if (fh == NULL) {
+        *err = errno;
